package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="inventory_physical_count_line") public class LineaConteoFisico{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="inventory_physical_count_id",nullable=false,updatable=false)private UUID conteoId;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="product_id",nullable=false,updatable=false)private UUID productoId;@Column(name="unit_of_measure_id",nullable=false,updatable=false)private UUID unidadId;
 @Column(name="initial_system_quantity",nullable=false,updatable=false)private BigDecimal cantidadInicial;@Column(name="counted_quantity")private BigDecimal cantidadContada;@Column(name="final_counted_quantity")private BigDecimal cantidadFinal;@Column(name="theoretical_quantity")private BigDecimal cantidadTeorica;@Column(name="difference_quantity")private BigDecimal diferencia;@Column(name="product_code_snapshot",nullable=false,updatable=false)private String codigo;@Column(name="product_name_snapshot",nullable=false,updatable=false)private String producto;@Column(name="unit_snapshot",nullable=false,updatable=false)private String unidad;@Column(name="counted_at")private OffsetDateTime contadoEn;@Column(name="counted_by")private UUID contadoPor;@Column(name="line_order",nullable=false,updatable=false)private int orden;@Version private long version;
 protected LineaConteoFisico(){}public LineaConteoFisico(ConteoFisico c,Producto p,BigDecimal inicial,int orden){conteoId=c.getId();tenantId=c.getTenantId();empresaId=c.getEmpresaId();productoId=p.getId();unidadId=p.getUnidadMedidaId();cantidadInicial=inicial;codigo=p.getCodigo();producto=p.getNombre();unidad=p.getUnidadMedida()==null?"Unidad":p.getUnidadMedida().getNombre();this.orden=orden;}
 public void contar(BigDecimal q,UUID u){cantidadContada=q;contadoEn=OffsetDateTime.now();contadoPor=u;}public void cerrar(BigDecimal teorica){cantidadTeorica=teorica;cantidadFinal=cantidadContada;diferencia=cantidadFinal.subtract(teorica);}
 public UUID getId(){return id;}public UUID getConteoId(){return conteoId;}public UUID getProductoId(){return productoId;}public UUID getUnidadId(){return unidadId;}public BigDecimal getCantidadInicial(){return cantidadInicial;}public BigDecimal getCantidadContada(){return cantidadContada;}public BigDecimal getCantidadFinal(){return cantidadFinal;}public BigDecimal getCantidadTeorica(){return cantidadTeorica;}public BigDecimal getDiferencia(){return diferencia;}public String getCodigo(){return codigo;}public String getProducto(){return producto;}public String getUnidad(){return unidad;}public int getOrden(){return orden;}public long getVersion(){return version;}
}
